// Minimal HTTP/1.1 request-head parsing and response formatting.
package kvhttp

data class RequestHead(
    val method: String,
    val target: String,
    val contentLength: ULong,
    val expectContinue: Boolean,
)

sealed interface HeadParse {
    data class Ok(val head: RequestHead) : HeadParse

    /** The head is invalid; [status] (400, 501 or 505) says why. */
    data class Invalid(val status: Int) : HeadParse
}

class Response(
    val status: Int,
    val body: ByteArray = EMPTY_BODY,
    val contentType: String? = null,
) {
    /** Serialized status line and headers. A 204 carries neither body nor Content-Length. */
    fun encodeHead(): ByteArray {
        val head = if (status == 204) {
            "HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n"
        } else buildString {
            append("HTTP/1.1 ").append(status).append(' ').append(Http.reason(status)).append("\r\n")
            contentType?.let { append("Content-Type: ").append(it).append("\r\n") }
            append("Content-Length: ").append(body.size).append("\r\n")
            append("Connection: close\r\n\r\n")
        }
        return head.toByteArray(Charsets.ISO_8859_1)
    }

    /** Body bytes to send after the head. */
    fun encodedBody(): ByteArray = if (status == 204) EMPTY_BODY else body

    companion object {
        val EMPTY_BODY = ByteArray(0)
    }
}

object Http {
    val CONTINUE_LINE: ByteArray = "HTTP/1.1 100 Continue\r\n\r\n".toByteArray(Charsets.ISO_8859_1)

    private const val TOKEN_SYMBOLS = "!#$%&'*+-.^_`|~"
    private val MAX_LENGTH_BEFORE_DIGIT = (ULong.MAX_VALUE - 9u) / 10u

    /**
     * Returns the length of the request head (through the blank line) if the first [len] bytes of
     * [buf] contain a complete head, otherwise 0. Accepts both CRLF CRLF and bare LF LF terminators.
     * Scanning starts at [from], which lets callers skip bytes already known to hold no terminator.
     */
    fun headLength(buf: ByteArray, len: Int, from: Int = 0): Int {
        for (i in from until len - 1) {
            if (buf[i] != LF) continue
            if (buf[i + 1] == LF) return i + 2
            if (buf[i + 1] == CR && i + 2 < len && buf[i + 2] == LF) return i + 3
        }
        return 0
    }

    /** Parses a complete request head occupying the first [headLen] bytes of [buf]. */
    fun parseHead(buf: ByteArray, headLen: Int): HeadParse {
        val text = String(buf, 0, headLen, Charsets.ISO_8859_1)
        val end = text.length

        // Tolerate leading empty lines (RFC 9112 section 2.2).
        var p = 0
        while (p < end && (text[p] == '\r' || text[p] == '\n')) p++

        var eol = text.indexOf('\n', p)
        if (eol < 0) return HeadParse.Invalid(400)
        val (method, target) = when (val line = parseRequestLine(text.substring(p, eol))) {
            is RequestLine.Ok -> line.method to line.target
            is RequestLine.Invalid -> return HeadParse.Invalid(line.status)
        }

        var contentLength: ULong? = null
        var expectContinue = false
        p = eol + 1
        while (p < end) {
            eol = text.indexOf('\n', p)
            if (eol < 0) return HeadParse.Invalid(400)
            val raw = text.substring(p, eol)
            p = eol + 1
            val line = raw.trimHttp()
            if (line.isEmpty()) break // end of head
            if (raw[0] == ' ' || raw[0] == '\t') return HeadParse.Invalid(400) // obsolete line folding

            val colon = line.indexOf(':')
            if (colon <= 0) return HeadParse.Invalid(400)
            val name = line.substring(0, colon)
            if (!name.all(::isTokenChar)) return HeadParse.Invalid(400)
            val value = line.substring(colon + 1).trimHttp()

            when {
                name.equals("Content-Length", ignoreCase = true) -> {
                    val n = parseLength(value) ?: return HeadParse.Invalid(400)
                    if (contentLength != null && contentLength != n) return HeadParse.Invalid(400)
                    contentLength = n
                }
                name.equals("Transfer-Encoding", ignoreCase = true) ->
                    if (!value.equals("identity", ignoreCase = true)) return HeadParse.Invalid(501)
                name.equals("Expect", ignoreCase = true) ->
                    if (value.equals("100-continue", ignoreCase = true)) expectContinue = true
            }
        }
        return HeadParse.Ok(RequestHead(method, target, contentLength ?: 0u, expectContinue))
    }

    fun reason(status: Int): String = when (status) {
        100 -> "Continue"
        200 -> "OK"
        201 -> "Created"
        204 -> "No Content"
        400 -> "Bad Request"
        404 -> "Not Found"
        405 -> "Method Not Allowed"
        408 -> "Request Timeout"
        413 -> "Content Too Large"
        431 -> "Request Header Fields Too Large"
        500 -> "Internal Server Error"
        501 -> "Not Implemented"
        503 -> "Service Unavailable"
        505 -> "HTTP Version Not Supported"
        else -> "Unknown"
    }

    private sealed interface RequestLine {
        data class Ok(val method: String, val target: String) : RequestLine
        data class Invalid(val status: Int) : RequestLine
    }

    private fun parseRequestLine(line: String): RequestLine {
        val sp1 = line.indexOf(' ')
        if (sp1 < 0) return RequestLine.Invalid(400)
        val sp2 = line.indexOf(' ', sp1 + 1)
        if (sp2 < 0) return RequestLine.Invalid(400)

        val method = line.substring(0, sp1)
        val target = line.substring(sp1 + 1, sp2)
        val version = line.substring(sp2 + 1).trimHttp()

        if (method.isEmpty() || target.isEmpty()) return RequestLine.Invalid(400)
        if (!method.all(::isTokenChar)) return RequestLine.Invalid(400)
        val wellFormed = version.length == 8 && version.startsWith("HTTP/") &&
            version[5].isAsciiDigit() && version[6] == '.' && version[7].isAsciiDigit()
        if (!wellFormed) return RequestLine.Invalid(400)
        if (version[5] != '1') return RequestLine.Invalid(505)
        return RequestLine.Ok(method, target)
    }

    /** Parses a Content-Length value: one or more digits, no sign, no overflow. */
    private fun parseLength(value: String): ULong? {
        if (value.isEmpty()) return null
        var n = 0uL
        for (c in value) {
            if (!c.isAsciiDigit() || n > MAX_LENGTH_BEFORE_DIGIT) return null
            n = n * 10u + (c - '0').toULong()
        }
        return n
    }

    private fun isTokenChar(c: Char): Boolean =
        c.isAsciiDigit() || c in 'a'..'z' || c in 'A'..'Z' || c in TOKEN_SYMBOLS

    private fun Char.isAsciiDigit() = this in '0'..'9'

    /** Strips leading spaces/tabs and trailing spaces/tabs/CRs. */
    private fun String.trimHttp(): String =
        trimStart(' ', '\t').trimEnd(' ', '\t', '\r')

    private const val CR = '\r'.code.toByte()
    private const val LF = '\n'.code.toByte()
}

// kvhttp: an in-memory HTTP/1.1 key-value server. Usage: app <port>
package kvhttp

import java.io.IOException
import kotlin.system.exitProcess

fun main(args: Array<String>) {
    val port = args.singleOrNull()?.toIntOrNull()?.takeIf { it in 1..65535 }
    if (port == null) {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    try {
        Server(port, Router(KvStore())).run()
    } catch (e: IOException) {
        System.err.println("kvhttp: ${e.message}")
        exitProcess(1)
    }
}

// Maps parsed HTTP requests onto key-value store operations.
package kvhttp

const val MAX_KEY_LENGTH = 64
const val MAX_VALUE_LENGTH = 1024 * 1024

class Router(private val store: KvStore) {

    fun route(head: RequestHead, body: ByteArray): Response {
        val path = head.target
        return when {
            path == "/health" ->
                if (head.method == "GET") Response(200, OK_BODY, "text/plain") else Response(405)
            path == "/kv" ->
                if (head.method == "GET") listKeys() else Response(405)
            path.startsWith(KV_PREFIX) -> {
                val key = path.substring(KV_PREFIX.length)
                if (isValidKey(key)) handleKey(head.method, key, body) else Response(400)
            }
            else -> Response(404)
        }
    }

    private fun handleKey(method: String, key: String, body: ByteArray): Response = when (method) {
        "GET" -> store[key]?.let { Response(200, it, "application/octet-stream") } ?: Response(404)
        "PUT" -> Response(if (store.put(key, body)) 201 else 200)
        "DELETE" -> Response(if (store.delete(key)) 204 else 404)
        else -> Response(405)
    }

    /** Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required. */
    private fun listKeys(): Response {
        val json = store.sortedKeys().joinToString(",", "[", "]") { "\"$it\"" }
        return Response(200, json.toByteArray(Charsets.US_ASCII), "application/json")
    }

    private companion object {
        const val KV_PREFIX = "/kv/"
        val OK_BODY = "ok".toByteArray(Charsets.US_ASCII)

        fun isValidKey(key: String): Boolean =
            key.length in 1..MAX_KEY_LENGTH &&
                key.all { it in 'A'..'Z' || it in 'a'..'z' || it in '0'..'9' || it == '_' || it == '-' }
    }
}

// HTTP server: one virtual thread per connection, one request per connection.
package kvhttp

import java.io.IOException
import java.io.InputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.SocketTimeoutException
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import kotlin.math.max
import kotlin.math.min

class Server(private val port: Int, private val router: Router) {

    /** Binds 127.0.0.1:[port] and serves forever. Throws [IOException] if the port cannot be bound. */
    fun run() {
        ServerSocket().use { listener ->
            listener.reuseAddress = true
            listener.bind(InetSocketAddress(InetAddress.getLoopbackAddress(), port), BACKLOG)
            Executors.newVirtualThreadPerTaskExecutor().use { executor ->
                while (!listener.isClosed) {
                    val socket = try {
                        listener.accept()
                    } catch (e: IOException) {
                        if (listener.isClosed) break
                        System.err.println("kvhttp: accept: ${e.message}")
                        continue
                    }
                    executor.execute { Connection(socket, router).serve() }
                }
            }
        }
    }

    private companion object {
        const val BACKLOG = 4096
    }
}

/** Serves exactly one request on [socket], then closes it. */
private class Connection(private val socket: Socket, private val router: Router) {
    /** Overall budget for receiving the request and sending the response. */
    private var deadline = System.nanoTime() + IO_TIMEOUT_NANOS

    fun serve() {
        socket.use {
            try {
                it.tcpNoDelay = true
                val response = readRequest(it.getInputStream()) ?: return
                send(response)
                drain(it.getInputStream())
            } catch (_: IOException) {
                // Peer went away or the connection timed out; nothing more to do.
            }
        }
    }

    /** Reads one request and produces its response, or returns null if the client left early. */
    private fun readRequest(input: InputStream): Response? {
        val buf = ByteArray(MAX_HEAD)
        var len = 0
        var headLen = 0
        while (headLen == 0) {
            if (len == MAX_HEAD) return Response(431)
            val n = read(input, buf, len, MAX_HEAD - len)
            if (n < 0) return null
            val scanFrom = max(0, len - 2)
            len += n
            headLen = Http.headLength(buf, len, scanFrom)
        }

        val head = when (val parsed = Http.parseHead(buf, headLen)) {
            is HeadParse.Ok -> parsed.head
            is HeadParse.Invalid -> return Response(parsed.status)
        }
        if (head.contentLength > MAX_VALUE_LENGTH.toULong()) return Response(413)

        val body = ByteArray(head.contentLength.toInt())
        var filled = min(len - headLen, body.size)
        buf.copyInto(body, 0, headLen, headLen + filled)
        if (head.expectContinue && filled < body.size) {
            socket.getOutputStream().apply { write(Http.CONTINUE_LINE); flush() }
        }
        while (filled < body.size) {
            val n = read(input, body, filled, body.size - filled)
            if (n < 0) return null
            filled += n
        }
        return router.route(head, body)
    }

    private fun send(response: Response) {
        socket.getOutputStream().apply {
            write(response.encodeHead())
            write(response.encodedBody())
            flush()
        }
    }

    /**
     * Half-closes and discards whatever the client still sends, so that unread request bytes do not
     * trigger a RST that could discard the response.
     */
    private fun drain(input: InputStream) {
        socket.shutdownOutput()
        deadline = System.nanoTime() + DRAIN_TIMEOUT_NANOS
        val scratch = ByteArray(DRAIN_CHUNK)
        while (read(input, scratch, 0, scratch.size) >= 0) {
            // discard
        }
    }

    /** A read bounded by the connection deadline. */
    private fun read(input: InputStream, into: ByteArray, off: Int, len: Int): Int {
        val remainingMillis = TimeUnit.NANOSECONDS.toMillis(deadline - System.nanoTime())
        if (remainingMillis <= 0) throw SocketTimeoutException("connection deadline passed")
        socket.soTimeout = remainingMillis.toInt()
        return input.read(into, off, len)
    }

    private companion object {
        const val MAX_HEAD = 64 * 1024
        const val DRAIN_CHUNK = 16 * 1024
        val IO_TIMEOUT_NANOS = TimeUnit.SECONDS.toNanos(30)
        val DRAIN_TIMEOUT_NANOS = TimeUnit.SECONDS.toNanos(2)
    }
}

package kvhttp

import java.util.concurrent.ConcurrentHashMap

/** Thread-safe in-memory key-value store. Values are stored as given; callers must not mutate them. */
class KvStore {
    private val entries = ConcurrentHashMap<String, ByteArray>()

    /** Stores [value] under [key]; returns true if the key was new. */
    fun put(key: String, value: ByteArray): Boolean = entries.put(key, value) == null

    operator fun get(key: String): ByteArray? = entries[key]

    /** Removes [key]; returns true if it was present. */
    fun delete(key: String): Boolean = entries.remove(key) != null

    /** Every key, sorted ascending. */
    fun sortedKeys(): List<String> = entries.keys.sorted()
}
